<?php
add_filter('wpnb_openai_endpoint',static fn():string=>get_option('wpnb_test_invalid_ai',0)?'https://example.org/v1/invalid-responses':'https://example.org/v1/responses');

add_action('rest_api_init',static function():void{
    $permission=static fn(WP_REST_Request$request):bool=>hash_equals('1',(string)$request->get_header('x-wpnb-test'));
    register_rest_route('wpnb-test/v1','/state',['methods'=>'GET','permission_callback'=>$permission,'callback'=>static function():array{
        global$wpdb;$prefix=$wpdb->prefix.'wpnb_';$engines=[];foreach(['sources','feed_items','jobs','ai_generations','logs','daily_usage','migration_journal']as$table){$status=$wpdb->get_row($wpdb->prepare('SHOW TABLE STATUS LIKE %s',$prefix.$table),ARRAY_A);$engines[$table]=strtolower((string)($status['Engine']??''));}
        $posts=get_posts(['post_type'=>'post','post_status'=>['draft','pending','publish','future','private'],'numberposts'=>-1,'fields'=>'ids','meta_key'=>'_wpnb_feed_item_id']);$postRecords=[];foreach($posts as$id){$feedId=(int)get_post_meta($id,'_wpnb_feed_item_id',true);$sourceItem=$wpdb->get_row($wpdb->prepare("SELECT title,excerpt,status,wordpress_post_id FROM {$prefix}feed_items WHERE id=%d",$feedId),ARRAY_A);$thumbnailId=(int)get_post_thumbnail_id($id);$postRecords[]=['id'=>(int)$id,'title'=>(string)get_the_title($id),'content'=>(string)get_post_field('post_content',$id),'status'=>(string)get_post_status($id),'feed_status'=>(string)($sourceItem['status']??''),'linked_post_id'=>(int)($sourceItem['wordpress_post_id']??0),'source_title'=>(string)($sourceItem['title']??''),'source_excerpt'=>(string)($sourceItem['excerpt']??''),'source_id'=>(int)get_post_meta($id,'_wpnb_source_id',true),'source_url'=>(string)get_post_meta($id,'_wpnb_source_url',true),'feed_item_id'=>$feedId,'content_hash'=>(string)get_post_meta($id,'_wpnb_content_hash',true),'ai_provider'=>(string)get_post_meta($id,'_wpnb_ai_provider',true),'ai_model'=>(string)get_post_meta($id,'_wpnb_ai_model',true),'generated_at'=>(string)get_post_meta($id,'_wpnb_generated_at',true),'thumbnail_id'=>$thumbnailId,'thumbnail_mime'=>$thumbnailId?(string)get_post_mime_type($thumbnailId):'','thumbnail_alt'=>$thumbnailId?(string)get_post_meta($thumbnailId,'_wp_attachment_image_alt',true):'','thumbnail_caption'=>$thumbnailId?(string)get_post_field('post_excerpt',$thumbnailId):'','thumbnail_content'=>$thumbnailId?(string)get_post_field('post_content',$thumbnailId):''];}
        $attachments=get_posts(['post_type'=>'attachment','post_status'=>'inherit','numberposts'=>-1,'fields'=>'ids','meta_key'=>'_wpnb_image_file_hash']);$media=[];foreach($attachments as$id){$file=(string)get_attached_file($id);$dimensions=$file!==''&&is_file($file)?@getimagesize($file):false;$media[]=['id'=>(int)$id,'mime'=>(string)get_post_mime_type($id),'exists'=>$file!==''&&is_file($file),'real_image'=>is_array($dimensions),'hash'=>(string)get_post_meta($id,'_wpnb_image_file_hash',true),'source_url_protected'=>(string)get_post_meta($id,'_wpnb_source_image_url',true)];}
