    register_rest_route('wpnb-test/v1','/invalid-ai',['methods'=>'POST','permission_callback'=>$permission,'callback'=>static function(WP_REST_Request$request):array{$enabled=(bool)$request->get_param('enabled');update_option('wpnb_test_invalid_ai',$enabled?1:0,false);return['enabled'=>$enabled];}]);
    register_rest_route('wpnb-test/v1','/publication-mode',['methods'=>'POST','permission_callback'=>$permission,'callback'=>static function(WP_REST_Request$request):array{$mode=sanitize_key((string)$request->get_param('mode'));if(!in_array($mode,['publish','draft'],true))return['saved'=>false];$settings=(array)get_option('wpnb_settings',[]);$settings['publication_mode']=$mode;update_option('wpnb_settings',$settings,false);return['saved'=>true,'mode'=>$mode];}]);
    register_rest_route('wpnb-test/v1','/post-status',['methods'=>'GET','permission_callback'=>$permission,'callback'=>static function(WP_REST_Request$request):array{$id=absint($request->get_param('id'));return['id'=>$id,'status'=>(string)get_post_status($id),'plugin_owned'=>(int)get_post_meta($id,'_wpnb_feed_item_id',true)>0];}]);
    register_rest_route('wpnb-test/v1','/seed-legacy-drafts',['methods'=>'POST','permission_callback'=>$permission,'callback'=>static function():array{global$wpdb;$prefix=$wpdb->prefix.'wpnb_';$source=$wpdb->get_row("SELECT * FROM {$prefix}sources ORDER BY id ASC LIMIT 1",ARRAY_A);$attachment=(int)$wpdb->get_var("SELECT image_attachment_id FROM {$prefix}feed_items WHERE image_attachment_id>0 ORDER BY id ASC LIMIT 1");$now=current_time('mysql',true);$guid='legacy-'.wp_generate_uuid4();$item=['source_id'=>(int)$source['id'],'source_name'=>(string)$source['name'],'source_feed_url'=>(string)$source['feed_url'],'guid'=>$guid,'source_url'=>'https://example.com/items/'.$guid,'normalized_url'=>'https://example.com/items/'.$guid,'title'=>'Legacy source headline','excerpt'=>'Legacy fixture excerpt','source_category'=>'Test','wordpress_category_id'=>1,'wordpress_post_id'=>0,'content_hash'=>hash('sha256',$guid),'image_url'=>'','image_source'=>'','image_status'=>'ready','image_attachment_id'=>$attachment,'image_hash'=>'','image_error_code'=>'','published_at'=>$now,'status'=>'processed','raw_data'=>null,'created_at'=>$now,'updated_at'=>$now];$wpdb->insert($prefix.'feed_items',$item);$itemId=(int)$wpdb->insert_id;$content='<p>Doğrulanmış bilgiler bağımsız ve açık bir haber metni olarak hazırlandı. İçerik kalite kontrollerinden geçebilmesi için yeterli ayrıntıyı güvenli biçimde sunar ve herhangi bir uzak bağlantı ya da görünür kaynak dipnotu içermez.</p>';$postId=(int)wp_insert_post(['post_title'=>'Legacy plugin draft','post_content'=>$content,'post_excerpt'=>'Güvenli eski taslak özeti kalite kontrolü için hazırlandı.','post_status'=>'draft','post_type'=>'post','post_category'=>[1]]);foreach(['_wpnb_source_id'=>(int)$source['id'],'_wpnb_source_url'=>(string)$item['source_url'],'_wpnb_feed_item_id'=>$itemId,'_wpnb_content_hash'=>$item['content_hash'],'_wpnb_ai_provider'=>'fixture','_wpnb_ai_model'=>'fixture','_wpnb_generated_at'=>$now]as$key=>$value)update_post_meta($postId,$key,$value);set_post_thumbnail($postId,$attachment);$wpdb->update($prefix.'feed_items',['wordpress_post_id'=>$postId],['id'=>$itemId]);$foreign=(int)wp_insert_post(['post_title'=>'Foreign draft must stay private','post_content'=>$content,'post_status'=>'draft','post_type'=>'post','post_category'=>[1]]);return['plugin_draft'=>$postId,'foreign_draft'=>$foreign,'item_id'=>$itemId];}]);
    register_rest_route('wpnb-test/v1','/image-settings',['methods'=>'POST','permission_callback'=>$permission,'callback'=>static function():array{$settings=(array)get_option('wpnb_settings',[]);$settings['image_min_width']=1;$settings['image_min_height']=1;$settings['image_max_bytes']=5242880;update_option('wpnb_settings',$settings,false);return['saved'=>true];}]);
    register_rest_route('wpnb-test/v1','/image-test',['methods'=>'POST','permission_callback'=>$permission,'callback'=>static function(WP_REST_Request$request):array{
        global$wpdb;$prefix=$wpdb->prefix.'wpnb_';$kind=sanitize_key((string)$request->get_param('kind'));$urls=['broken'=>'https://example.com/images/broken.jpg','oversized'=>'https://example.com/images/large.png','fake_mime'=>'https://example.com/images/fake.jpg','redirect'=>'https://example.com/images/redirect.png','private_redirect'=>'https://example.com/images/private-redirect.png','private_ip'=>'https://127.0.0.1/image.png'];if(!isset($urls[$kind]))return['status'=>'error','error_code'=>'invalid_test'];$sourceId=(int)$wpdb->get_var("SELECT id FROM {$prefix}sources ORDER BY id ASC LIMIT 1");$now=current_time('mysql',true);$guid='image-test-'.$kind.'-'.wp_generate_uuid4();$record=['source_id'=>$sourceId,'source_name'=>'Image safety fixture','source_feed_url'=>'https://example.com/news-atom.xml','guid'=>$guid,'source_url'=>'https://example.com/items/'.$guid,'normalized_url'=>'https://example.com/items/'.$guid,'title'=>'Image safety '.$kind,'excerpt'=>'Image safety fixture','source_category'=>'Test','wordpress_category_id'=>1,'content_hash'=>hash('sha256',$guid),'image_url'=>$urls[$kind],'image_source'=>'e2e','image_status'=>'missing','image_attachment_id'=>0,'image_hash'=>'','image_error_code'=>'','published_at'=>$now,'status'=>'new','raw_data'=>null,'created_at'=>$now,'updated_at'=>$now];$wpdb->insert($prefix.'feed_items',$record);$itemId=(int)$wpdb->insert_id;$settings=(array)get_option('wpnb_settings',[]);$settings['image_max_bytes']=$kind==='oversized'?65536:5242880;$settings['image_min_width']=1;$settings['image_min_height']=1;update_option('wpnb_settings',$settings,false);$result=(new \WordPressNewsBot\ImageImportService())->import($itemId);$result['item_id']=$itemId;return$result;
